1	"use client";
2	import { useEffect, useMemo, useState } from "react";
3	import { formatTokens } from "@/lib/format-tokens";
4	import { toolTitle } from "@/lib/tool-registry";
5	import {
6	  buildToolTree,
7	  countToolTree,
8	  subagentLabel,
9	  walkToolTree,
10	  type ToolNode,
11	} from "@/lib/tool-tree";
12	import type { ToolCall, ToolCallStats } from "@/lib/types";
13	import { useSessionStore } from "@/stores/sessionStore";
14	import { ToolRow, useElapsed } from "./ToolRow";
15	
16	// The turn's whole tool timeline, in chronological order, one row per call.
17	//
18	// Replaces the old pair of panels (🔧 工具调用 for the main agent + a separate
19	// 🤖 子 Agent box). Splitting them meant delegated work had to be *removed*
20	// from the main list to appear in its own box, so the two panels each told
21	// half the story and neither preserved the order things actually happened in.
22	// One tree, nested where nesting is real, is both simpler and more honest.
23	//
24	// 大会话的 toolCalls 不随会话载荷下发（占比能到 98%，改发预计算 stats），
25	// 所以 done 节点首次展开时按需拉取（loadNodeToolCalls）；拉取期间折叠态
26	// 用 stats 渲染角标数字。流式节点不受影响——toolCalls 随流事件进 store。
27	
28	export function ToolTimeline({
29	  nodeId,
30	  toolCalls,
31	  stats,
32	  live,
33	}: {
34	  nodeId: string;
35	  toolCalls: ToolCall[];
36	  stats?: ToolCallStats | null;
37	  live: boolean;
38	}) {
39	  const tree = useMemo(() => buildToolTree(toolCalls), [toolCalls]);
40	  const counts = useMemo(() => countToolTree(tree), [tree]);
41	  // null = follow the run: open while it streams (watching it work is the
42	  // point), collapsed once it's done (the answer is). A click pins it.
43	  const [userOpen, setUserOpen] = useState<boolean | null>(null);
44	  const open = userOpen ?? live;
45	
46	  // 折叠态在 toolCalls 未加载时用 stats 顶上（tree 为空但 stats 有数字）。
47	  const display = tree.length > 0 ? counts : stats ?? null;
48	  // toolCalls 被剥离、且这轮确实有工具调用 → 展开时按需拉取。
49	  const needsLoad = toolCalls.length === 0 && (stats?.total ?? 0) > 0;
50	  const loadNodeToolCalls = useSessionStore((s) => s.loadNodeToolCalls);
51	  const loading = useSessionStore((s) => Boolean(s.toolCallsLoading[nodeId]));
52	  useEffect(() => {
53	    if (open && needsLoad) void loadNodeToolCalls(nodeId);
54	  }, [open, needsLoad, nodeId, loadNodeToolCalls]);
55	
56	  if (!display || display.total === 0) return null;
57	  const running = live ? walkToolTree(tree).filter((n) => n.running) : [];
58	
59	  return (
60	    <div className="mb-3 border border-line rounded-card overflow-hidden bg-surface-muted/60">
61	      <button
62	        type="button"
63	        onClick={() => setUserOpen(!open)}
64	        aria-expanded={open}
65	        className="w-full px-3 py-2 flex items-center gap-2 text-ui text-left hover:bg-surface-muted transition-colors"
66	      >
67	        <span
68	          className="text-ink-faint transition-transform shrink-0"
69	          style={{ transform: open ? "rotate(90deg)" : "rotate(0)" }}
70	          aria-hidden
71	        >
72	          ▸
73	        </span>
74	        {running.length > 0 ? (
75	          <LiveHeader running={running} />
76	        ) : (
77	          <>
78	            <span className="font-medium text-ink shrink-0">🧰 动线</span>
79	            <span className="text-ink-muted tabular-nums shrink-0">
80	              {display.total} 步
81	            </span>
82	            <span className="text-ink-faint truncate min-w-0">
83	              {summaryLine(tree, display.subagents, display.workflows)}
84	            </span>
85	            {display.errors > 0 && (
86	              <span className="text-danger-ink shrink-0">
87	                · {display.errors} 失败
88	              </span>
89	            )}
90	          </>
91	        )}
92	        <span className="flex-1" />
93	        <span className="text-nano text-ink-faint hidden sm:inline shrink-0">
94	          {open ? "收起" : "展开"}
95	        </span>
96	      </button>
97	
98	      {open &&
99	        (tree.length > 0 ? (
100	          <div className="border-t border-line divide-y divide-line/70">
101	            {tree.map((n) => (
102	              <ToolRow key={n.call.id} node={n} live={live} />
103	            ))}
104	          </div>
105	        ) : (
106	          // toolCalls 还在按需拉取（或拉取失败静默降级）——给一行占位，
107	          // 别让展开的面板空着。
108	          <div className="border-t border-line px-3 py-2 text-ui text-ink-faint flex items-center gap-2">
109	            {loading ? (
110	              <>
111	                <span className="w-1.5 h-1.5 rounded-full bg-accent animate-pulse" />
112	                正在加载工具调用…
113	              </>
114	            ) : (
115	              <span>工具调用暂无数据</span>
116	            )}
117	          </div>
118	        ))}
119	    </div>
120	  );
121	}
122	
123	// The folded-state live line — the reason a collapsed panel is acceptable at
124	// all. Without it a folded timeline meant the user had no idea anything was
125	// happening. Deepest running node wins: while a sub-agent runs, what you want
126	// to see is the tool *it* is running, not the word "Agent".
127	function LiveHeader({ running }: { running: ToolNode[] }) {
128	  const node = running[running.length - 1];
